export class AppState { draft: string = ""; submitted: string = ""; }
export class ChangeDraft { value: string = ""; }
export class Submit {}
export function initialState(): AppState { return {draft: "", submitted: ""}; }
// @ui-update
export function changeDraft(state: AppState, action: ChangeDraft): AppState { return {draft: action.value, submitted: state.submitted}; }
// @ui-update
export function submit(state: AppState, action: Submit): AppState { return {draft: state.draft, submitted: state.draft}; }

