import * as app from "./app.deal";
import * as ui from "./platform-ui.dealui-pack";

// @ui-root
export view App(state: app.AppState): View {
  ui.Root() {
    ui.Column() {
      ui.TextField(label: "Draft", onChange: action app.ChangeDraft {value: payload}, value: state.draft)
      ui.Button(onClick: action app.Submit {}, text: "Apply")
      ui.Text(value: state.submitted)
    }
  }
}
